// Change Line Chart — Basic, route: jsx
// Source: change-line-chart_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo, useId } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from changeLine ----
type ChangePoint = { date: Date; close: number };

/** The reference price every value is expressed relative to. */
const BASIS = 100;

const DAYS = 260;

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

/**
 * Synthetic daily closes: two sine cycles carry the price back and forth across the
 * basis six times, and a correlated random walk keeps the path from looking drawn.
 */
const stockCloses: ChangePoint[] = (() => {
  let drift = 0;
  return Array.from({ length: DAYS }, (_, day) => {
    drift = drift * 0.92 + (random() - 0.5) * 1.6;
    const cycle =
      22 * Math.sin((2 * Math.PI * day) / 86) + 6 * Math.sin((2 * Math.PI * day) / 31);
    return { date: new Date(Date.UTC(2024, 0, 1 + day)), close: BASIS + cycle + drift };
  });
})();

/** Daily closes, plus the basis every close is expressed as a change from. */
export type Data = { closes: { date: Date; close: number }[]; basis: number };

type Close = Data['closes'][number];

const DEMO: Data = { closes: stockCloses, basis: BASIS };

const MARGIN = { top: 28, right: 20, bottom: 36, left: 56 };
const GAIN = d3.schemeRdYlGn[3][2];
const LOSS = d3.schemeRdYlGn[3][0];

/** 1.2 reads as "+20%", and parity reads as "0%" rather than "+0%". */
const percentChange = (ratio: number) =>
  ratio === 1 ? '0%' : d3.format('+.0%')(ratio - 1);

export default function ChangeLineChart({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const { closes, basis } = data;
  const clipId = useId();
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(closes, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [closes, innerWidth]
  );

  // A log scale makes a +50% move the same visual distance as the -33% that undoes it.
  const y = useMemo(
    () =>
      d3
        .scaleLog()
        .domain([
          (d3.min(closes, (d) => d.close / basis) ?? 1) * 0.9,
          (d3.max(closes, (d) => d.close / basis) ?? 1) / 0.9
        ])
        .rangeRound([innerHeight, 0]),
    [closes, basis, innerHeight]
  );

  const parityY = y(1);

  // One area spanning from the parity rule to the line; the two clips split it by sign.
  const area = useMemo(
    () =>
      d3
        .area<Close>()
        .x((d) => x(d.date))
        .y0(parityY)
        .y1((d) => y(d.close / basis))(closes) ?? '',
    [closes, basis, x, y, parityY]
  );

  const line = useMemo(
    () =>
      d3
        .line<Close>()
        .x((d) => x(d.date))
        .y((d) => y(d.close / basis))(closes) ?? '',
    [closes, basis, x, y]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(3, Math.round(innerWidth / 80)))
        .map((v) => ({ value: d3.utcFormat('%b')(v), offset: x(v) })),
    [x, innerWidth]
  );

  // Evenly spaced percentages, not the log scale's own powers of ten.
  const yTicks: Tick[] = useMemo(() => {
    const [lo, hi] = y.domain();
    return d3.ticks(lo, hi, 8).map((v) => ({ value: percentChange(v), offset: y(v) }));
  }, [y]);

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Line chart of a stock price as percent change from its opening basis, with gains and losses shaded">
      <defs>
        <clipPath id={`${clipId}-gain`}>
          <rect x={0} y={0} width={innerWidth} height={Math.max(parityY, 0)} />
        </clipPath>
        <clipPath id={`${clipId}-loss`}>
          <rect x={0} y={parityY} width={innerWidth}
                height={Math.max(innerHeight - parityY, 0)} />
        </clipPath>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={area} fill={GAIN} fillOpacity={0.75} clipPath={`url(#${clipId}-gain)`} />
        <path d={area} fill={LOSS} fillOpacity={0.75} clipPath={`url(#${clipId}-loss)`} />
        <line x1={0} x2={innerWidth} y1={parityY} y2={parityY}
              stroke="var(--text)" strokeWidth={1} />
        <path d={line} fill="none" stroke="var(--text)" strokeWidth={1.25}
              strokeLinejoin="round" strokeLinecap="round" />
        <text x={-MARGIN.left} y={-10} fill="var(--muted)" fontSize={11}>
          {`↑ Change from $${basis.toFixed(2)} basis`}
        </text>
        {innerWidth >= 280 && (
          <g transform={`translate(${innerWidth},-10)`} fontSize={11} fill="var(--muted)"
             textAnchor="end">
            <rect x={-108} y={-9} width={10} height={10} fill={GAIN} />
            <text x={-60} dy="-0.1em">above</text>
            <rect x={-46} y={-9} width={10} height={10} fill={LOSS} />
            <text x={0} dy="-0.1em">below</text>
          </g>
        )}
      </g>
    </svg>
  );
}
